import pandas as pd
import numpy as np

def clean(df):
    df = df.copy()
    # strip whitespace from object columns
    for col in df.select_dtypes(include=['object']).columns:
        df[col] = df[col].apply(lambda x: x.strip() if isinstance(x, str) else x)
    # normalise sex
    if 'sex' in df.columns:
        df['sex'] = df['sex'].replace({'': np.nan, 'nan': np.nan, 'None': np.nan})
        df['sex'] = df['sex'].astype(object).apply(lambda x: x.strip().lower() if isinstance(x, str) else x)
    # numeric conversion
    num_cols = ['bill_length_mm','bill_depth_mm','flipper_length_mm','body_mass_g','year']
    for col in num_cols:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce')
    # flipper length negative -> take absolute value
    if 'flipper_length_mm' in df.columns:
        df['flipper_length_mm'] = df['flipper_length_mm'].abs()
    # body_mass_g out of range: values >6500 are likely mg, convert to g
    if 'body_mass_g' in df.columns:
        mask = df['body_mass_g'] > 6500
        df.loc[mask, 'body_mass_g'] = df.loc[mask, 'body_mass_g'] / 1000.0
    return df

def answer(df):
    dfc = clean(df)
    dfc = dfc.dropna(subset=['species','body_mass_g'])
    avg = dfc.groupby('species')['body_mass_g'].mean()
    return {str(k): float(v) for k, v in avg.items()}
